import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int maxAttempts = s.nextInt(), n = s.nextInt();
        Set<String> done = new HashSet<>();
        int processed = 0, skipped = 0, retried = 0, dlq = 0;
        for (int i = 0; i < n; i++) {
            String id = s.next();
            int attempt = s.nextInt();
            String outcome = s.next();
            if (done.contains(id)) {
                System.out.println("SKIP " + id);
                skipped++;
            } else if (outcome.equals("ok")) {
                done.add(id);
                System.out.println("PROCESS " + id);
                processed++;
            } else if (outcome.equals("permanent")) {
                System.out.println("DLQ " + id);
                dlq++;
            } else if (attempt >= maxAttempts) {
                System.out.println("DLQ " + id);
                dlq++;
            } else {
                System.out.println("RETRY " + id + " " + (attempt + 1));
                retried++;
            }
        }
        System.out.println("SUMMARY processed=" + processed + " skipped=" + skipped + " retried=" + retried + " dlq=" + dlq);
    }
}
